namespace Weymela.Application;
public interface IAuthorizationService{void Demand(Actor actor,ActorRole role);void DemandBusinessOwner(Actor actor,Guid businessId);void DemandCreatorSelf(Actor actor,Guid creatorId);}
public sealed class AuthorizationService:IAuthorizationService{public void Demand(Actor actor,ActorRole role){if(actor.Role!=role)throw new ApplicationFailure(FailureKind.Forbidden,"Forbidden.");}public void DemandBusinessOwner(Actor actor,Guid businessId){Demand(actor,ActorRole.Business);if(actor.BusinessId!=businessId)throw new ApplicationFailure(FailureKind.Forbidden,"Business resource ownership failed.");}public void DemandCreatorSelf(Actor actor,Guid creatorId){Demand(actor,ActorRole.Creator);if(actor.CreatorId!=creatorId)throw new ApplicationFailure(FailureKind.Forbidden,"Creator resource ownership failed.");}}
